// Builds database/seed/seed.sql from seed-data.ts and the demo artwork list.
// Run: node database/seed/build-seed.ts
import { writeFileSync } from "node:fs";
import * as d from "./seed-data.ts";

const q = (s: string | null | undefined) => (s == null ? "null" : `'${String(s).replace(/'/g, "''")}'`);
const j = (o: unknown) => `${q(JSON.stringify(o ?? {}))}::jsonb`;
const arr = (a: string[]) => (a.length ? `array[${a.map(q).join(",")}]::text[]` : `'{}'::text[]`);
const out: string[] = [
  "-- GENERATED by database/seed/build-seed.ts — edit seed-data.ts instead.",
  "-- Safe to re-run: keyed rows use ON CONFLICT, list content is inserted only into empty tables.",
  "begin;",
];
const push = (s: string) => out.push(s.trim() + ";");

// roles & permissions
for (const r of d.roles)
  push(`insert into roles(key,name,description,is_system,position) values (${q(r.key)},${j(r.name)},${j(r.description)},true,${r.position}) on conflict (key) do nothing`);
d.permissions.forEach(([key, group, desc], i) =>
  push(`insert into permissions(key,group_key,description,position) values (${q(key)},${q(group)},${j(desc)},${i}) on conflict (key) do nothing`));
for (const [role, perms] of Object.entries(d.rolePermissions))
  for (const p of perms) push(`insert into role_permissions(role_key,permission_key) values (${q(role)},${q(p)}) on conflict do nothing`);

// languages & translations
for (const l of d.languages)
  push(`insert into languages(code,name,native_name,dir,is_default,position) values (${q(l.code)},${q(l.name)},${q(l.native_name)},${q(l.dir)},${l.is_default},${l.position}) on conflict (code) do nothing`);
for (const [key, v] of Object.entries(d.translations))
  for (const loc of ["ar", "en"] as const)
    push(`insert into translations(key,locale,value,group_key) values (${q(key)},${q(loc)},${q(v[loc])},${q(key.split(".")[0])}) on conflict (key,locale) do nothing`);

// settings & brand & templates
for (const [key, s] of Object.entries(d.settings))
  push(`insert into site_settings(key,value,is_public) values (${q(key)},${j(s.value)},${s.is_public ?? true}) on conflict (key) do nothing`);
const b = d.brand;
push(`insert into brand_settings(id,name,tagline,description,logo_mode,default_theme,radius,colors,fonts) values (1,${j(b.name)},${j(b.tagline)},${j(b.description)},${q(b.logo_mode)},${q(b.default_theme)},${q(b.radius)},${j(b.colors)},${j(b.fonts)}) on conflict (id) do nothing`);
for (const [key, tpl] of Object.entries(d.notificationTemplates))
  push(`insert into notification_templates(key,subject,body) values (${q(key)},${j(tpl.subject)},${j(tpl.body)}) on conflict (key) do nothing`);

// services
d.serviceCategories.forEach((c, i) =>
  push(`insert into service_categories(slug,name,description,icon,position,is_demo) values (${q(c.slug)},${j(c.name)},${j(c.description)},${q(c.icon)},${i},true) on conflict (slug) do nothing`));
for (const s of d.services)
  push(`insert into services(slug,category_id,title,excerpt,body,icon,features,steps,faqs,technologies,status,is_featured,position,is_demo)
    select ${q(s.slug)},(select id from service_categories where slug=${q(s.cat)}),${j(s.title)},${j(s.excerpt)},${j(s.body)},${q(s.icon)},${j(s.features)},${j(s.steps)},${j(s.faqs)},${arr(s.tech)},'published',${!!s.featured},${s.position},true
    on conflict (slug) do nothing`);

// projects
d.projectCategories.forEach((c, i) =>
  push(`insert into project_categories(slug,name,position,is_demo) values (${q(c.slug)},${j(c.name)},${i},true) on conflict (slug) do nothing`));
for (const p of d.projects) {
  push(`insert into projects(slug,category_id,title,excerpt,body,challenge,solution,results,metrics,client_name,project_type,cover_url,completed_on,technologies,status,is_featured,position,is_demo,show_on_home,home_position)
    select ${q(p.slug)},(select id from project_categories where slug=${q(p.cat)}),${j(p.title)},${j(p.excerpt)},${j(p.body)},${j(p.challenge)},${j(p.solution)},${j(p.results)},${j(p.metrics)},${j(p.client)},${j(p.type)},${q(p.cover)},${q(p.date)},${arr(p.tech)},'published',${!!p.featured},${p.position},true,${!!p.featured},${p.position}
    on conflict (slug) do nothing`);
  p.gallery.forEach((url, i) =>
    push(`insert into project_images(project_id,url,position) select id,${q(url)},${i} from projects where slug=${q(p.slug)} and not exists (select 1 from project_images pi join projects pp on pp.id=pi.project_id where pp.slug=${q(p.slug)} and pi.url=${q(url)})`));
  for (const s of p.services)
    push(`insert into project_services(project_id,service_id) select p.id,s.id from projects p, services s where p.slug=${q(p.slug)} and s.slug=${q(s)} on conflict do nothing`);
}

// team
d.team.forEach((m, i) =>
  push(`insert into team_members(slug,name,job_title,bio,skills,social,is_founder,position,is_demo) values (${q(m.slug)},${j(m.name)},${j(m.job)},${j(m.bio)},${arr(m.skills)},${j({ linkedin: "https://www.linkedin.com/" })},${m.founder},${i},true) on conflict (slug) do nothing`));

// blog
d.blogCategories.forEach((c, i) =>
  push(`insert into blog_categories(slug,name,position,is_demo) values (${q(c.slug)},${j(c.name)},${i},true) on conflict (slug) do nothing`));
for (const tg of d.blogTags) push(`insert into blog_tags(slug,name,is_demo) values (${q(tg.slug)},${j(tg.name)},true) on conflict (slug) do nothing`);
for (const p of d.posts) {
  push(`insert into blog_posts(slug,category_id,author_id,title,excerpt,body,cover_url,reading_minutes,status,is_featured,published_at,is_demo)
    select ${q(p.slug)},(select id from blog_categories where slug=${q(p.cat)}),(select id from team_members where slug=${q(p.author)}),${j(p.title)},${j(p.excerpt)},${j(p.body)},${q(p.cover)},4,'published',${!!p.featured},${q(p.published_at)},true
    on conflict (slug) do nothing`);
  for (const tg of p.tags)
    push(`insert into blog_post_tags(post_id,tag_id) select p.id,t.id from blog_posts p, blog_tags t where p.slug=${q(p.slug)} and t.slug=${q(tg)} on conflict do nothing`);
}

// testimonials & clients (only into empty tables)
d.testimonials.forEach((x, i) =>
  push(`insert into testimonials(author_name,author_title,quote,rating,position,is_demo) select ${j(x.name)},${j(x.title)},${j(x.quote)},${x.rating},${i},true where not exists (select 1 from testimonials where is_demo and position=${i})`));
d.clients.forEach((c, i) =>
  push(`insert into clients(name,description,logo_url,position,is_demo) select ${j(c.name)},${j(c.description)},${q(`/demo/client-${i + 1}.svg`)},${i},true where not exists (select 1 from clients where is_demo and position=${i})`));

// pages & sections
d.pages.forEach((p, i) => {
  push(`insert into pages(slug,kind,title,summary,status,position) values (${q(p.slug)},${q(p.kind)},${j(p.title)},${j(p.summary)},'published',${i}) on conflict (slug) do nothing`);
  p.sections.forEach((s, k) =>
    push(`insert into page_sections(page_id,type,position,content,settings) select id,${q(s.type)},${k},${j(s.content)},${j(s.settings ?? {})} from pages where slug=${q(p.slug)} and not exists (select 1 from page_sections ps join pages pg on pg.id=ps.page_id where pg.slug=${q(p.slug)} and ps.position=${k})`));
});

// navigation
for (const [menu, items] of Object.entries(d.navigation)) {
  items.forEach((it: { label: unknown; href: string; children?: { label: unknown; href: string }[] }, i: number) => {
    const guard = `not exists (select 1 from navigation_items where menu=${q(menu)} and parent_id is null and position=${i})`;
    if (!it.children) {
      push(`insert into navigation_items(menu,label,href,position) select ${q(menu)},${j(it.label)},${q(it.href)},${i} where ${guard}`);
    } else {
      const children = it.children
        .map((c, k) => `(${j(c.label)},${q(c.href)},${k})`)
        .join(",");
      push(`with parent as (insert into navigation_items(menu,label,href,position) select ${q(menu)},${j(it.label)},${q(it.href)},${i} where ${guard} returning id)
        insert into navigation_items(menu,parent_id,label,href,position) select ${q(menu)},parent.id,c.label,c.href,c.pos from parent, (values ${children}) as c(label,href,pos)`);
    }
  });
}

out.push("commit;");
writeFileSync(new URL("./seed.sql", import.meta.url), out.join("\n") + "\n");
console.log(`seed.sql written (${out.length} statements)`);
